<template>
  <div class="page-im-channels">
    <CrudToolbar :title="t('notifier.imTitle')" :can-create="authStore.isAdmin" @create="onCreate" />

    <el-card>
      <DataTable
        v-model:current-page="page"
        v-model:page-size="pageSize"
        :data="imChannels"
        :loading="loading"
        :server-side="true"
        :total="total"
      >
        <el-table-column prop="name" :label="t('common.name')" min-width="180" />
        <el-table-column prop="channel_type" :label="t('common.type')" width="120">
          <template #default="{ row }">
            {{ imTypeLabel(row.channel_type) }}
          </template>
        </el-table-column>
        <el-table-column prop="enabled" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="row.enabled ? 'success' : 'info'" size="small">
              {{ row.enabled ? t('common.enabled') : t('common.disabled') }}
            </el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="config.webhook" label="Webhook" min-width="240">
          <template #default="{ row }">
            <el-text truncated>{{ row.config.webhook }}</el-text>
          </template>
        </el-table-column>
        <el-table-column prop="created_at" :label="t('common.createdAt')" min-width="160">
          <template #default="{ row }">
            {{ formatTime(row.created_at) }}
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="260" fixed="right">
          <template #default="{ row }">
            <el-button link type="primary" size="small" @click="onTest(row)">
              {{ t('common.test') }}
            </el-button>
            <el-button v-if="authStore.isAdmin" link type="primary" size="small" @click="onEdit(row)">
              {{ t('common.edit') }}
            </el-button>
            <ConfirmButton
              v-if="authStore.isAdmin"
              :title="t('notifier.confirmDeleteImChannel')"
              confirm-button-type="danger"
              @confirm="onDelete(row)"
            >
              <el-button link type="danger" size="small">{{ t('common.delete') }}</el-button>
            </ConfirmButton>
          </template>
        </el-table-column>
      </DataTable>
    </el-card>

    <el-dialog
      v-model="dialogVisible"
      :title="isEdit ? t('notifier.imForm.editTitle') : t('notifier.imForm.createTitle')"
      width="560px"
      :close-on-click-modal="false"
      @closed="onClosed"
    >
      <el-form ref="formRef" :model="form" :rules="rules" label-width="100px">
        <el-form-item :label="t('common.name')" prop="name">
          <el-input v-model="form.name" :placeholder="t('notifier.imForm.namePlaceholder')" />
        </el-form-item>
        <el-form-item :label="t('common.platform')" prop="channel_type">
          <el-select v-model="form.channel_type" :disabled="isEdit" @change="onTypeChange">
            <el-option :label="t('notifier.imForm.dingtalk')" value="dingtalk" />
            <el-option :label="t('notifier.imForm.wecom')" value="wecom" />
            <el-option :label="t('notifier.imForm.lark')" value="lark" />
            <el-option label="Slack" value="slack" />
          </el-select>
        </el-form-item>
        <el-form-item label="Webhook" prop="webhook">
          <el-input
            v-model="form.webhook"
            type="textarea"
            :rows="2"
            :placeholder="t('notifier.imForm.webhookPlaceholder')"
          />
        </el-form-item>
        <el-form-item v-if="needsSecret" :label="t('notifier.imForm.secret')">
          <el-input
            v-model="form.secret"
            type="password"
            show-password
            :placeholder="t('notifier.imForm.secretPlaceholder')"
          />
        </el-form-item>
        <el-form-item :label="t('common.enable')">
          <el-switch v-model="form.enabled" />
        </el-form-item>
      </el-form>

      <template #footer>
        <el-button @click="dialogVisible = false">{{ t('common.cancel') }}</el-button>
        <el-button type="primary" :loading="submitting" @click="onSubmit">
          {{ isEdit ? t('common.save') : t('common.create') }}
        </el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { useAuthStore } from '@/stores/auth'
import {
  createNotificationChannel,
  deleteNotificationChannel,
  getNotificationChannels,
  testNotificationChannel,
  updateNotificationChannel,
  type NotificationChannelRead,
  type NotificationChannelType,
} from '@/api/notificationChannels'
import { useListQuery } from '@/composables/useListQuery'
import ConfirmButton from '@/components/common/ConfirmButton.vue'
import DataTable from '@/components/common/DataTable.vue'
import CrudToolbar from '@/components/common/CrudToolbar.vue'
import { showError } from '@/utils/error'

const { t } = useI18n()
const authStore = useAuthStore()

const IM_TYPES: NotificationChannelType[] = ['dingtalk', 'wecom', 'lark', 'slack']

const imChannels = ref<NotificationChannelRead[]>([])
const total = ref(0)
const loading = ref(false)
const dialogVisible = ref(false)
const selectedChannel = ref<NotificationChannelRead | null>(null)
const submitting = ref(false)
const isEdit = ref(false)

const { page, pageSize } = useListQuery({
  defaults: {},
  parse: () => ({}),
  serialize: () => ({}),
})

const formRef = ref<FormInstance>()
const form = ref({
  name: '',
  channel_type: 'dingtalk' as NotificationChannelType,
  webhook: '',
  secret: '',
  enabled: true,
})

const needsSecret = computed(() => form.value.channel_type === 'dingtalk' || form.value.channel_type === 'lark')

const rules: FormRules = {
  name: [{ required: true, message: () => t('notifier.channelForm.nameRequired'), trigger: 'blur' }],
  channel_type: [{ required: true, message: () => t('notifier.imForm.platformRequired'), trigger: 'change' }],
  webhook: [{ required: true, message: () => t('notifier.imForm.webhookRequired'), trigger: 'blur' }],
}

function imTypeLabel(type: string) {
  const map: Record<string, string> = {
    dingtalk: t('notifier.imForm.dingtalk'),
    wecom: t('notifier.imForm.wecom'),
    lark: t('notifier.imForm.lark'),
    slack: 'Slack',
  }
  return map[type] || type
}

async function loadChannels() {
  loading.value = true
  try {
    const response = await getNotificationChannels({
      page: page.value,
      page_size: pageSize.value,
    })
    imChannels.value = response.items.filter((item) => IM_TYPES.includes(item.channel_type))
    total.value = imChannels.value.length
  } catch (error) {
    showError(error, t('notifier.loadImChannelsFailed'))
  } finally {
    loading.value = false
  }
}

function onCreate() {
  selectedChannel.value = null
  isEdit.value = false
  resetForm()
  dialogVisible.value = true
}

function onEdit(row: NotificationChannelRead) {
  selectedChannel.value = row
  isEdit.value = true
  form.value = {
    name: row.name,
    channel_type: row.channel_type as NotificationChannelType,
    webhook: String(row.config.webhook || ''),
    secret: '',
    enabled: row.enabled,
  }
  dialogVisible.value = true
}

async function onTest(row: NotificationChannelRead) {
  try {
    const result = await testNotificationChannel(row.id)
    ElMessage[result.success ? 'success' : 'error'](result.message)
  } catch (error) {
    showError(error, t('notifier.testFailed'))
  }
}

async function onDelete(row: NotificationChannelRead) {
  try {
    await deleteNotificationChannel(row.id)
    ElMessage.success(t('notifier.channelDeleted'))
    loadChannels()
  } catch (error) {
    showError(error, t('common.deleteFailed'))
  }
}

function onTypeChange() {
  form.value.secret = ''
}

function resetForm() {
  form.value = {
    name: '',
    channel_type: 'dingtalk',
    webhook: '',
    secret: '',
    enabled: true,
  }
}

function onClosed() {
  formRef.value?.resetFields()
  resetForm()
}

async function onSubmit() {
  const valid = await formRef.value?.validate().catch(() => false)
  if (!valid) return

  submitting.value = true
  try {
    const config: Record<string, unknown> = {
      webhook: form.value.webhook,
    }
    if (needsSecret.value && form.value.secret) {
      config.secret = form.value.secret
    }

    const data = {
      name: form.value.name,
      channel_type: form.value.channel_type,
      enabled: form.value.enabled,
      config,
    }

    if (isEdit.value && selectedChannel.value) {
      await updateNotificationChannel(selectedChannel.value.id, data)
    } else {
      await createNotificationChannel(data)
    }
    ElMessage.success(isEdit.value ? t('notifier.channelUpdated') : t('notifier.channelCreated'))
    dialogVisible.value = false
    loadChannels()
  } catch (error) {
    showError(error, isEdit.value ? t('notifier.updateChannelFailed') : t('notifier.createChannelFailed'))
  } finally {
    submitting.value = false
  }
}

function formatTime(value: string) {
  return new Date(value).toLocaleString()
}

watch(
  () => ({ page: page.value, pageSize: pageSize.value }),
  loadChannels,
  { deep: true, immediate: true }
)
</script>

<style scoped>
.page-im-channels {
  padding: 20px;
}
</style>
